sources.GiveawayManagerV2.sol:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.21;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import {MerkleProof} from "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {IVRFCoordinatorV2Plus} from "@chainlink/contracts/src/v0.8/vrf/dev/interfaces/IVRFCoordinatorV2Plus.sol";
import {VRFV2PlusClient} from "@chainlink/contracts/src/v0.8/vrf/dev/libraries/VRFV2PlusClient.sol";

import {IPrizeModule, PrizeKind} from "./IPrizeModule.sol";

/**
 * @title GiveawayManagerV2
 * @notice INSTANT WIN Event Center, giveaway core. Hosts many concurrent, independent free-entry
 *         giveaways, with winners drawn by Chainlink VRF 2.5 and prizes custodied by per-type
 *         modules. Standalone and immutable: no proxy, no upgrade path, no admin power over an
 *         outcome. RaffleManagerV3 is untouched.
 *
 * @dev Implements SPEC-GIVEAWAY-V2 (scope closed 2026-09-01), which folds in a scope audit and a
 *      security audit of V1 (0x1F2aE94Fd04Ce15cb2A3a09B7b81eb9e16781cB0, Arbitrum One). Every
 *      correction carries its spec code (C1..C11, S1..S8) at the line that implements it.
 *
 *      WHAT V1 GOT RIGHT AND THIS CONTRACT REPRODUCES UNCHANGED:
 *
 *      1. WINNER DERIVATION. Winner i is participants[keccak256(seed, attempt) % n], with an
 *         already-selected index skipped and the attempt counter advanced permanently. The result
 *         is invariant to the caller and to how the batching splits the work. Nobody who calls
 *         it, and nobody who entered, can move it.
 *
 *      2. CHECKS-EFFECTS-INTERACTIONS on every path that moves value, with nonReentrant on every
 *         function that transfers.
 *
 *      3. MERKLE with a 20-byte address leaf against 64-byte internal nodes: disjoint preimage
 *         spaces, so no second-preimage ambiguity.
 *
 *      4. INDIVISIBLE REMAINDER handed to the first derived winner exactly, so the sum over
 *         winners is the prize to the wei.
 *
 *      WHAT CHANGED, BY DESIGN:
 *
 *      A. THE CORE NEVER HOLDS A PRIZE (section 2.2). Custody and delivery live in one immutable
 *         module per prize type; the core keeps the lifecycle, the randomness, the derivation,
 *         the eligibility, the fees and the slots. A campaign is bound to its module at creation
 *         and that binding never moves, so deploying a new module cannot reach a running one.
 *
 *      B. ENTRY IS BRIDGE-GATED (section 3). There is no open-entry mode. An address enters only
 *         by proving membership of a Merkle root the bridge published, which is what closes the
 *         V1 finding where a campaign with a zero root could be filled with an attacker's own
 *         wallets and its prize captured outright.
 *
 *      C. CLOSING IS SEPARATE FROM ASKING FOR RANDOMNESS (S1). The VRF request lives in its own
 *         permissionless, retryable step out of the CLOSED state, so a coordinator that reverts
 *         can no longer strand every campaign in OPEN.
 *
 *      D. THE CONTRACT IS BORN PAUSED (S4). No deposit is accepted before the owner has confirmed
 *         the VRF consumer registration and unpaused.
 *
 *      The VRF consumer callback is implemented inline rather than by inheriting
 *      VRFConsumerBaseV2Plus, because that base bundles ConfirmedOwner, which conflicts with OZ
 *      Ownable2Step. The coordinator-only check is identical. Same reasoning as V1 and V3.
 */
contract GiveawayManagerV2 is Ownable2Step, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ============================================================
    // CONSTANTS — section 9.1 (carried from V1) and 9.2 (new). No setters by design.
    // ============================================================

    /// @notice Protocol fee on a token prize, in basis points. Flat 5%.
    uint256 public constant FEE_BPS = 500;
    /// @notice Protocol fee on an NFT prize, in basis points of the creator's declared value.
    ///         Half the token rate: NFT custody is heavier and the value is not verifiable
    ///         on-chain, so the competitive rate is the deliberate choice (section 7.3).
    uint256 public constant NFT_FEE_BPS = 250;
    uint256 private constant BPS = 10_000;

    /// @notice Shortest giveaway. Below an hour there is no real participation window.
    uint256 public constant MIN_DURATION = 1 hours;
    /// @notice Longest giveaway. Beyond a month it is a different product.
    uint256 public constant MAX_DURATION = 30 days;
    /// @notice Winners per giveaway.
    uint256 public constant MAX_WINNERS = 1_000;
    /// @notice Hard ceiling on slots a creator may buy, and therefore on entrants.
    uint256 public constant MAX_PARTICIPANTS = 100_000;

    /// @notice Floor on entrants (C2). Below it a giveaway cancels at close rather than settling,
    ///         which also absorbs the separate zero-entries branch V1 had.
    uint256 public constant MIN_PARTICIPANTS = 10;

    /// @notice How long a giveaway may wait for its draw before anyone may rescue it. Measured
    ///         from the VRF request, and from the close for a campaign whose request never landed.
    uint256 public constant DRAW_TIMEOUT = 24 hours;

    /**
     * @notice How long the timeout rescue stays open once DRAW_TIMEOUT has elapsed (S2).
     * @dev V1 left cancelStuckDraw eligible forever after the timeout, which left a late VRF
     *      delivery racing a cancellation for as long as the campaign lived: an observer who can
     *      derive the winner set from a fulfilment in flight, and does not like it, cancels the
     *      draw instead. Bounding the rescue to a window bounds that exposure. Nothing is
     *      stranded by the bound, because a request that outlives its window is expired back to
     *      CLOSED by {expireDrawRequest} and the whole cycle becomes available again.
     */
    uint256 public constant RESCUE_WINDOW = 24 hours;

    /// @notice How long a winner has to claim, from settlement (C6). After it the creator
    ///         recovers what nobody took. One rule for token and NFT alike.
    uint256 public constant CLAIM_DEADLINE = 90 days;

    /// @notice How far into the entry window slots may still be topped up, in basis points
    ///         (section 7.2: up to 75% of the entry time elapsed).
    uint256 public constant RELOAD_WINDOW_BPS = 7_500;

    /**
     * @notice Derivation attempts {finalizeWinners} performs per call.
     * @dev The batching bound, counted in attempts rather than winners, so a call can never spin
     *      unboundedly on collisions: every attempt advances the cursor permanently, so
     *      successive calls always make progress. Changing it changes only how many calls a
     *      settle takes, never which wallets win nor in what order.
     */
    uint256 public constant FINALIZE_STEPS = 100;

    uint16 private constant REQUEST_CONFIRMATIONS = 3;
    /// @dev One word. The whole winner set expands deterministically from this single seed.
    uint32 private constant NUM_WORDS = 1;

    /// @dev VRF 2.5 callback gas bounds enforced on the constructor argument (S7). The floor is
    ///      what storing one seed and one status costs with headroom; the ceiling is the
    ///      coordinator's own documented maximum, above which a request can never be served.
    uint32 private constant MIN_CALLBACK_GAS = 100_000;
    uint32 private constant MAX_CALLBACK_GAS = 2_500_000;

    /// @notice GiveawayCancelled reason: kept for numbering stability only. C2 folds the
    ///         zero-entries case into REASON_BELOW_MINIMUM, so this is never emitted.
    uint8 public constant REASON_ZERO_ENTRIES = 0;
    /// @notice GiveawayCancelled reason: creator cancelled while OPEN and nobody had entered.
    uint8 public constant REASON_CREATOR = 1;
    /// @notice GiveawayCancelled reason: the draw could not be obtained within DRAW_TIMEOUT.
    uint8 public constant REASON_VRF_TIMEOUT = 2;
    /// @notice GiveawayCancelled reason: closed with fewer than MIN_PARTICIPANTS entrants (C2).
    uint8 public constant REASON_BELOW_MINIMUM = 3;

    /**
     * @notice Giveaway lifecycle (section 9.3). NONE means the id was never created.
     * @dev CLOSED sits between OPEN and DRAW_REQUESTED and is the whole of S1: closing a campaign
     *      is pure state, and asking the coordinator for randomness is a separate, retryable step
     *      that anyone may drive. A coordinator that reverts then costs liveness on one
     *      transaction instead of freezing every campaign in OPEN.
     */
    enum Status {
        NONE,
        OPEN,
        CLOSED,
        DRAW_REQUESTED,
        SEED_RECEIVED,
        SETTLED,
        CANCELLED
    }

    // ============================================================
    // IMMUTABLES — the entire VRF configuration, plus the accounting unit.
    // ============================================================

    /// @notice Chainlink VRF 2.5 coordinator. Immutable: whoever controls the coordinator
    ///         controls the randomness, and this contract grants nobody that power post-deploy.
    ///         It is the trust boundary of the whole system, which is why S7 validates it.
    IVRFCoordinatorV2Plus public immutable vrfCoordinator;
    /// @notice VRF 2.5 subscription id (public, not a secret). Owned by this contract alone and
    ///         deliberately NOT shared with RaffleManagerV3: a busy lottery must never be able to
    ///         starve a giveaway draw (S1).
    uint256 public immutable subscriptionId;
    /// @notice VRF gas lane.
    bytes32 public immutable keyHash;
    /// @notice Gas forwarded to {rawFulfillRandomWords}. The callback only stores a seed, so this
    ///         is small and constant regardless of winner count.
    uint32 public immutable callbackGasLimit;

    /// @notice The accounting unit for slots and for NFT-campaign fees (section 9.2). Immutable.
    IERC20 public immutable usdc;

    // ============================================================
    // OWNER-ADJUSTABLE PARAMETERS — section 7.3. Charged at creation, so an adjustment can never
    // reach a campaign already running.
    // ============================================================

    /// @notice Price of one entry slot, in USDC units (section 7.2). Charged on the whole cap the
    ///         creator buys, at the price current when they buy it.
    uint256 public pricePerSlot;
    /// @notice Floor on the fee of an NFT campaign, in USDC units (section 7.3). Keeps 2.5% of a
    ///         low declared value from rounding the campaign into being free.
    uint256 public nftMinFee;

    /// @notice The only address that may publish eligibility roots (sections 3.3 and 4.2).
    /// @dev Deliberately not the owner. The bridge signs once per identity it verifies, which is
    ///      the highest-frequency privileged action in the system; the owner key withdraws fees
    ///      and sweeps. Keeping them apart means a compromised bridge key can publish a bad root
    ///      but cannot move a single unit of value.
    address public bridge;

    /// @notice Prize modules the owner has approved for new campaigns. Read only at creation
    ///         (section 2.3): de-registering a module never disturbs a campaign already bound
    ///         to it.
    mapping(address => bool) public isModuleRegistered;

    // ============================================================
    // PAUSE ACCOUNTING — C5
    // ============================================================

    /// @notice When the pause currently in force began, or zero if not paused.
    uint64 public pausedAt;
    /// @notice Total seconds this contract has spent paused, across all completed pauses.
    /// @dev Every giveaway records this counter at creation, so its effective end time carries
    ///      exactly the pause time that fell inside its own life and none that fell before it.
    ///      Without this the owner could pause through an entry window and drive a campaign below
    ///      MIN_PARTICIPANTS on purpose.
    uint64 public totalPausedTime;

    // ============================================================
    // GIVEAWAY STATE
    // ============================================================

    /**
     * @dev The participants, winners and eligibility-root lists live in their own mappings rather
     *      than inside this struct, so {getGiveaway} can return the whole record in one call.
     */
    struct Giveaway {
        // --- slot 0
        address creator; //          who created and funded it
        uint64 startTime; //         when the entry window opened, for the slot reload window
        uint32 winnersCount; //      N winners; clamped down to the entrant count at close
        // --- slot 1
        address prizeModule; //      bound at creation, never reassigned (section 2.3)
        uint64 endTime; //           nominal end; the effective end adds pause time (C5)
        Status status;
        PrizeKind prizeKind; //      frozen from the module at creation
        uint8 cancelReason; //       meaningful only once CANCELLED
        // --- slot 2
        IERC20 feeToken; //          the prize token for a TOKEN campaign, USDC for an NFT one
        uint32 slotCap; //           entry slots bought, and therefore the entrant ceiling
        uint32 nextAttempt; //       finalizeWinners cursor, persists across batches
        // --- slot 3
        uint64 pausedOffset; //      totalPausedTime as it stood when this giveaway was created
        uint64 closedAt; //          entered CLOSED at, for the S1 timeout out of CLOSED
        uint64 drawRequestedAt; //   for the DRAW_TIMEOUT rescue and the S2 window
        uint64 settledAt; //         for the CLAIM_DEADLINE (C6)
        // --- one slot each
        uint256 prizeAmount; //      TOKEN: base units. NFT: item count.
        uint256 declaredValue; //    NFT only: the creator's public valuation, the fee base
        uint256 feeAmount; //        charged at creation, refundable only where C3 says so
        uint256 slotsPaid; //        USDC paid for slots, across creation and every reload
        uint256 prizeDelivered; //   what the module has handed out, in the prize unit
        uint256 vrfRequestId;
        uint256 seed; //             stored by the VRF callback, consumed by finalizeWinners
    }

    /// @notice Id of the most recent giveaway. Ids start at 1, so 0 is never a real giveaway,
    ///         which is what lets {rawFulfillRandomWords} reject an unknown requestId.
    uint256 public lastGiveawayId;

    mapping(uint256 => Giveaway) private _giveaways;
    mapping(uint256 => address[]) private _participants;
    mapping(uint256 => address[]) private _winners;

    /// @notice Append-only history of eligibility roots per giveaway (section 4.1). Roots are
    ///         added, never replaced and never removed, which is what makes "eligible once,
    ///         eligible forever" a structural property rather than a promise.
    mapping(uint256 => bytes32[]) private _eligibilityRoots;

    /// @notice One wallet, one entry. Also the participant-index bijection the winner derivation
    ///         relies on to detect an already-selected index.
    mapping(uint256 => mapping(address => bool)) public hasEntered;

    /// @dev Winner position plus one; zero means not a winner. Stored instead of a plain boolean
    ///      because an NFT campaign hands the n-th derived winner the n-th deposited item
    ///      (section 8.3), so the position has to survive to claim time. Costs the same single
    ///      cold write per winner that V1's boolean did, which matters because that write is what
    ///      dominates finalisation gas at MAX_WINNERS.
    mapping(uint256 => mapping(address => uint256)) private _winnerSlot;

    mapping(uint256 => mapping(address => bool)) public prizeClaimed;
    mapping(uint256 => bool) public creatorRefunded;

    /// @notice Whether the creator has taken back the NFT items left over by the close-time clamp
    ///         (section 8.4). Separate from {creatorRefunded}, which belongs to the cancellation
    ///         path: a settled giveaway and a cancelled one are never the same giveaway.
    mapping(uint256 => bool) public clampSurplusReclaimed;

    mapping(uint256 => uint256) public giveawayIdByRequestId;

    /// @notice Protocol fees available to {withdrawFees}, per token. Credited when a giveaway
    ///         settles, and when a cancellation retains a fee under C3.
    mapping(IERC20 => uint256) public feesAccrued;

    /**
     * @notice Everything this contract owes to somebody, per token: unwithdrawn protocol fees
     *         plus every fee and slot payment still refundable to a creator (C7).
     * @dev The sweep subtracts this from the real balance, so it can only ever remove value
     *      nobody has a claim on. Maintained as O(1) counters on the state transitions rather
     *      than by iterating campaigns. Prizes are absent by construction: they live in the
     *      modules and never pass through this contract.
     */
    mapping(IERC20 => uint256) public committed;

    // ============================================================
    // EVENTS — the proof layer. Section 11.4 links to these; S6 corrects them.
    // ============================================================

    event GiveawayCreated(
        uint256 indexed giveawayId,
        address indexed creator,
        address indexed prizeModule,
        PrizeKind prizeKind,
        address prizeToken,
        uint256 prizeAmount,
        uint256 declaredValue,
        IERC20 feeToken,
        uint256 feeAmount,
        uint64 endTime,
        uint32 winnersCount,
        uint32 slotCap,
        uint256 slotsPaid
    );
    /// @dev Section 4.2: every addition to the append-only root history is public.
    event EligibilityRootAdded(uint256 indexed giveawayId, uint256 indexed rootIndex, bytes32 root);
    event SlotsReloaded(uint256 indexed giveawayId, uint32 addedSlots, uint32 newSlotCap, uint256 paid);
    /// @dev J5: the index is the direct input to the winner derivation, so a log without it
    ///      cannot be used to reconstruct the draw.
    event Entered(uint256 indexed giveawayId, address indexed wallet, uint256 index);
    /// @dev J3: carries the post-clamp winner count, so a reader never has to derive it.
    ///      J4: not emitted at all when the same call cancels the giveaway instead of closing it.
    event GiveawayClosed(uint256 indexed giveawayId, uint256 participants, uint32 winnersCount);
    event RandomnessRequested(uint256 indexed giveawayId, uint256 indexed requestId);
    /// @dev S2: a request that outlived its rescue window, returning the giveaway to CLOSED.
    event DrawRequestExpired(uint256 indexed giveawayId, uint256 indexed requestId);
    event SeedReceived(uint256 indexed giveawayId, uint256 seed);
    /// @dev J2: the batch progress signal V1 had no equivalent for. Winners are published as they
    ///      are derived, so the whole draw is reconstructible from logs alone.
    event WinnersDerived(uint256 indexed giveawayId, uint256 fromIndex, address[] winners);
    /// @dev S5: deliberately does not carry the winner array, which is what made V1's last batch
    ///      cost several times the others and gave every caller a reason to wait for somebody
    ///      else. J1: publishes the remainder separately, so the event states exactly what each
    ///      winner is paid rather than a truncated share nobody actually receives.
    event GiveawaySettled(
        uint256 indexed giveawayId, uint32 winnersCount, uint256 sharePerWinner, uint256 remainderToFirstWinner
    );
    event GiveawayCancelled(uint256 indexed giveawayId, uint8 reason, uint256 feeRetained, uint256 slotsRetained);
    event PrizeClaimed(uint256 indexed giveawayId, address indexed winner, uint256 amount);
    event CreatorRefunded(uint256 indexed giveawayId, uint256 feeRefunded, uint256 slotsRefunded, uint256 prizeReturned);
    /// @dev Section 8.4: items the clamp left without a winner, returned with no waiting period.
    ///      Distinct from {UnclaimedPrizeReclaimed}, which is prize a winner could have taken and
    ///      did not — the two carry different meaning for anyone auditing a campaign.
    event ClampSurplusReclaimed(uint256 indexed giveawayId, uint256 amount);
    event UnclaimedPrizeReclaimed(uint256 indexed giveawayId, uint256 amount);
    event FeesWithdrawn(IERC20 indexed token, uint256 amount);
    event SurplusSwept(IERC20 indexed token, uint256 amount);
    event ModuleRegistered(address indexed module, bool allowed);
    event BridgeChanged(address indexed previousBridge, address indexed newBridge);
    event PricePerSlotChanged(uint256 previousPrice, uint256 newPrice);
    event NftMinFeeChanged(uint256 previousFee, uint256 newFee);

    // ============================================================
    // ERRORS
    // ============================================================

    error InvalidAddress();
    error InvalidDuration();
    error InvalidWinnersCount();
    error InvalidSlotCap();
    error InvalidPrizeAmount();
    error InvalidDeclaredValue();
    error InvalidRoot();
    error InvalidSubscription();
    error InvalidKeyHash();
    error InvalidCallbackGasLimit();
    error InvalidPrice();
    error ModuleNotRegistered();
    error PrizeTooSmall();
    error PrizeAmountMismatch();
    error TransferAmountMismatch();
    error GiveawayNotOpen();
    error EntriesClosed();
    error AlreadyEntered();
    error SlotsExhausted();
    error ReloadWindowClosed();
    error NotEligible();
    error NotDue();
    error NotCreator();
    error NotBridge();
    error NotClosed();
    error NotDrawRequested();
    error NotSeedReceived();
    error NotSettled();
    error HasParticipants();
    error TimeoutNotReached();
    error RescueWindowClosed();
    error ClaimExpired();
    error DeadlineNotReached();
    error RequestIdCollision();
    error OnlyCoordinator();
    error UnknownRequest();
    error NotCancelled();
    error AlreadyRefunded();
    error NothingToClaim();
    /// @dev The clamp-surplus path has its own three, rather than borrowing AlreadyRefunded and
    ///      NothingToClaim, because those would collapse three different situations into one
    ///      revert and leave anyone reading the failure unable to tell which happened.
    error ClampSurplusAlreadyReclaimed();
    error NotNftGiveaway();
    error NoClampSurplus();
    error NoSurplus();
    error RenounceDisabled();

    /**
     * @notice Deploys the core, paused (S4).
     * @dev Every argument is validated, because every one of them is either immutable or the
     *      trust boundary itself, and none is repairable without a redeploy (S7). V1 checked one
     *      of four: a coordinator pointing at an attacker's own contract passed that check, and
     *      from there it could have chosen the winners of every campaign the contract ever ran.
     *
     *      The contract is born paused and stays paused until the owner has, in order: created
     *      and funded its own VRF subscription, added this address as a consumer, and verified
     *      the registration (section 9.4). Until then no deposit is accepted, which is what
     *      closes the V1 window where campaigns could be created and funded before settlement was
     *      even possible.
     *
     * @param _vrfCoordinator   Chainlink VRF 2.5 coordinator. Must be a contract.
     * @param _subscriptionId   This contract's own VRF 2.5 subscription, not shared with the
     *                          lottery (S1).
     * @param _keyHash          VRF gas lane.
     * @param _callbackGasLimit Gas for the callback, within the bounds a coordinator will serve.
     * @param _usdc             Accounting unit for slots and NFT-campaign fees.
     * @param _bridge           Initial address allowed to publish eligibility roots.
     * @param _pricePerSlot     Initial price of one entry slot, in USDC units.
     * @param _nftMinFee        Initial floor on an NFT campaign's fee, in USDC units.
     */
    constructor(
        address _vrfCoordinator,
        uint256 _subscriptionId,
        bytes32 _keyHash,
        uint32 _callbackGasLimit,
        address _usdc,
        address _bridge,
        uint256 _pricePerSlot,
        uint256 _nftMinFee
    ) Ownable(msg.sender) {
        // S7 — all four VRF arguments, not just the zero-address one.
        if (_vrfCoordinator.code.length == 0) revert InvalidAddress();
        if (_subscriptionId == 0) revert InvalidSubscription();
        if (_keyHash == bytes32(0)) revert InvalidKeyHash();
        if (_callbackGasLimit < MIN_CALLBACK_GAS || _callbackGasLimit > MAX_CALLBACK_GAS) {
            revert InvalidCallbackGasLimit();
        }
        if (_usdc.code.length == 0) revert InvalidAddress();
        if (_bridge == address(0)) revert InvalidAddress();
        if (_pricePerSlot == 0 || _nftMinFee == 0) revert InvalidPrice();

        vrfCoordinator = IVRFCoordinatorV2Plus(_vrfCoordinator);
        subscriptionId = _subscriptionId;
        keyHash = _keyHash;
        callbackGasLimit = _callbackGasLimit;
        usdc = IERC20(_usdc);

        bridge = _bridge;
        pricePerSlot = _pricePerSlot;
        nftMinFee = _nftMinFee;

        // S4 — no deposits until the owner has confirmed this contract is a registered consumer.
        pausedAt = uint64(block.timestamp);
        _pause();

        emit BridgeChanged(address(0), _bridge);
        emit PricePerSlotChanged(0, _pricePerSlot);
        emit NftMinFeeChanged(0, _nftMinFee);
    }

    // ============================================================
    // CREATOR: CREATE AND FUND
    // ============================================================

    /**
     * @notice Create and fund a giveaway. The creator pays the prize, the protocol fee and the
     *         entry slots up front.
     * @dev The prize itself never enters this contract: the module pulls it from the creator, so
     *      the creator approves the MODULE for the prize and this contract for the fee and slots.
     *
     *      C11/S3 — the prize is rejected outright if the module received anything other than
     *      exactly what was declared, and the fee and slot transfers are held to the same rule.
     *      That single equality closes both fee-on-transfer tokens and tokens whose hooks can
     *      inflate a measured balance delta mid-transfer, which is how V1 could be made to charge
     *      a fee on less than it ended up distributing.
     *
     *      Price is the prize fee plus the whole slot cap (section 7.2). Buying the cap up front
     *      is what makes the sybil cost the attacker's problem instead of the platform's: filling
     *      a campaign with throwaway wallets is only possible up to a ceiling somebody has
     *      already paid for.
     *
     * @param module        A registered prize module. Binds the campaign for life (section 2.3).
     * @param prizeData     Module-specific prize description, passed through untouched.
     * @param prizeAmount   Prize to deposit: base units for a token campaign, item count for an
     *                      NFT one. Must match what the module reports receiving.
     * @param declaredValue NFT campaigns only: the creator's public valuation, which is the fee
     *                      base (section 7.3). Must be zero for a token campaign.
     * @param duration      Entry window, within [MIN_DURATION, MAX_DURATION].
     * @param winnersCount  Winners, within [1, MAX_WINNERS], clamped to the entrant count at
     *                      close. An NFT campaign must ask for exactly one winner per item
     *                      deposited (sections 8.1 and 8.3).
     * @param slotCap       Entry slots to buy, within [MIN_PARTICIPANTS, MAX_PARTICIPANTS].
     * @return giveawayId   The new giveaway's id.
     */
    function createGiveaway(
        address module,
        bytes calldata prizeData,
        uint256 prizeAmount,
        uint256 declaredValue,
        uint256 duration,
        uint32 winnersCount,
        uint32 slotCap
    ) external whenNotPaused nonReentrant returns (uint256 giveawayId) {
        if (!isModuleRegistered[module]) revert ModuleNotRegistered();
        if (duration < MIN_DURATION || duration > MAX_DURATION) revert InvalidDuration();
        if (winnersCount == 0 || uint256(winnersCount) > MAX_WINNERS) revert InvalidWinnersCount();
        // Below the floor the campaign is guaranteed to cancel at close (C2), so selling those
        // slots would be selling a campaign that cannot run.
        if (uint256(slotCap) < MIN_PARTICIPANTS || uint256(slotCap) > MAX_PARTICIPANTS) revert InvalidSlotCap();
        if (prizeAmount == 0) revert InvalidPrizeAmount();

        PrizeKind kind = IPrizeModule(module).prizeKind();
        if (kind == PrizeKind.NFT) {
            if (declaredValue == 0) revert InvalidDeclaredValue();
            // Section 8.3: the n-th derived winner takes the n-th deposited item, so a campaign
            // is created with exactly one winner per item. The close-time clamp is what produces
            // surplus items, and section 8.4 hands those back to the creator.
            if (uint256(winnersCount) != prizeAmount) revert InvalidWinnersCount();
        } else if (declaredValue != 0) {
            revert InvalidDeclaredValue();
        }

        giveawayId = ++lastGiveawayId;

        Giveaway storage g = _giveaways[giveawayId];
        g.creator = msg.sender;
        // The timestamp casts are safe: duration is capped at MAX_DURATION, so neither value can
        // approach the uint64 range for any block a chain will ever produce.
        g.startTime = uint64(block.timestamp);
        g.endTime = uint64(block.timestamp + duration);
        g.winnersCount = winnersCount;
        g.prizeModule = module;
        g.status = Status.OPEN;
        g.prizeKind = kind;
        g.slotCap = slotCap;
        // C5 — the baseline this campaign measures pause time against. Safe to read directly:
        // whenNotPaused means there is no pause in flight to add.
        g.pausedOffset = totalPausedTime;
        g.prizeAmount = prizeAmount;
        g.declaredValue = declaredValue;

        (address prizeToken, uint256 received) = IPrizeModule(module).takeCustody(giveawayId, msg.sender, prizeData);
        // C11/S3 — exact or nothing.
        if (received != prizeAmount) revert PrizeAmountMismatch();

        IERC20 feeToken = kind == PrizeKind.NFT ? usdc : IERC20(prizeToken);
        uint256 fee = currentFee(kind, kind == PrizeKind.NFT ? declaredValue : prizeAmount);
        // Dust guard: a fixed minimum cannot be one constant across arbitrary token decimals, so
        // it is enforced as "a prize whose fee rounds to zero is not a prize". NFT campaigns
        // cannot reach it, being floored by nftMinFee.
        if (fee == 0) revert PrizeTooSmall();

        uint256 slotsCost = uint256(slotCap) * pricePerSlot;

        g.feeToken = feeToken;
        g.feeAmount = fee;
        g.slotsPaid = slotsCost;

        committed[feeToken] += fee;
        committed[usdc] += slotsCost;

        _pullExact(feeToken, fee);
        _pullExact(usdc, slotsCost);

        emit GiveawayCreated(
            giveawayId,
            msg.sender,
            module,
            kind,
            prizeToken,
            prizeAmount,
            declaredValue,
            feeToken,
            fee,
            g.endTime,
            winnersCount,
            slotCap,
            slotsCost
        );
    }

    /**
     * @notice Buy more entry slots for a giveaway still taking entries.
     * @dev Priced at the rate current now, not the one that applied at creation (section 7.2): a
     *      top-up is a new purchase. Allowed only in the first RELOAD_WINDOW_BPS of the entry
     *      window, so a creator cannot watch a draw fill up and only then decide how large to
     *      make it.
     * @param giveawayId      Giveaway to top up. Caller must be its creator.
     * @param additionalSlots Slots to add, subject to the MAX_PARTICIPANTS ceiling.
     */
    function reloadSlots(uint256 giveawayId, uint32 additionalSlots) external whenNotPaused nonReentrant {
        Giveaway storage g = _giveaways[giveawayId];
        if (g.status != Status.OPEN) revert GiveawayNotOpen();
        if (msg.sender != g.creator) revert NotCreator();
        if (additionalSlots == 0) revert InvalidSlotCap();

        uint256 newCap = uint256(g.slotCap) + uint256(additionalSlots);
        if (newCap > MAX_PARTICIPANTS) revert InvalidSlotCap();

        // Measured on the effective window, so pause time cannot silently close the reload door.
        uint256 startTime = g.startTime;
        uint256 window = effectiveEndTime(giveawayId) - startTime;
        if (block.timestamp > startTime + (window * RELOAD_WINDOW_BPS) / BPS) revert ReloadWindowClosed();

        uint256 payment = uint256(additionalSlots) * pricePerSlot;
        // The cast is safe: newCap was just bounded by MAX_PARTICIPANTS, which is far inside uint32.
        uint32 cap = uint32(newCap);

        g.slotCap = cap;
        g.slotsPaid += payment;
        committed[usdc] += payment;

        _pullExact(usdc, payment);

        emit SlotsReloaded(giveawayId, additionalSlots, cap, payment);
    }

    /**
     * @dev Transfer in and insist on the exact amount (C11/S3). V1 measured the delta and recorded
     *      whatever arrived, which is correct accounting but leaves the fee computed on a
     *      different number from the one distributed. Rejecting the token instead is explicit,
     *      cheap, and closes fee-on-transfer and transfer-hook inflation in a single check.
     *      Rebasing tokens remain unsupported and are documented as such in the UI.
     */
    function _pullExact(IERC20 token, uint256 amount) private {
        uint256 balanceBefore = token.balanceOf(address(this));
        token.safeTransferFrom(msg.sender, address(this), amount);
        if (token.balanceOf(address(this)) - balanceBefore != amount) revert TransferAmountMismatch();
    }

    // ============================================================
    // BRIDGE: ELIGIBILITY — section 4, append-only
    // ============================================================

    /**
     * @notice Publish another eligibility root for a giveaway still open.
     * @dev Append-only by construction (section 4.1). There is no function that replaces or
     *      removes a root, so an address that was ever eligible stays eligible for the life of
     *      the campaign: it can always prove itself against the root it was written into, however
     *      many roots come after. That is what makes "nobody is removed once admitted"
     *      (section 3.4) a property of the contract rather than a policy somebody has to police.
     *
     *      The bridge publishes these as it verifies identities, which is why the whole
     *      anti-sybil funnel runs before an address is ever written on chain and never after.
     *
     * @param giveawayId Giveaway to extend. Must be OPEN (section 4.2).
     * @param root       Merkle root over 20-byte address leaves.
     */
    function addEligibilityRoot(uint256 giveawayId, bytes32 root) external whenNotPaused {
        if (msg.sender != bridge) revert NotBridge();
        if (root == bytes32(0)) revert InvalidRoot();

        Giveaway storage g = _giveaways[giveawayId];
        if (g.status != Status.OPEN) revert GiveawayNotOpen();

        bytes32[] storage roots = _eligibilityRoots[giveawayId];
        roots.push(root);

        emit EligibilityRootAdded(giveawayId, roots.length - 1, root);
    }

    // ============================================================
    // PARTICIPANT: ENTER — free, one wallet one entry, bridge-authorised only
    // ============================================================

    /**
     * @notice Enter a giveaway. Free: no participant funds are ever collected.
     * @dev Section 3.2 and S8 — there is no open-entry mode. A caller enters only by proving
     *      membership of a root the bridge published, so a campaign with no roots yet accepts
     *      nobody, and a campaign with roots accepts exactly the addresses the bridge verified.
     *      This is the correction with the largest economic weight in the whole spec: in V1 a
     *      campaign with a zero root was free to enter and unrestricted, so an attacker could
     *      fill it with their own wallets and take the prize in expectation, with the bridge
     *      paying the gas for the attack against itself.
     *
     *      Section 4.1 — any root in the history is accepted, current or long superseded.
     *
     *      No transfers and no external calls, so no reentrancy guard: this is the function paid
     *      for up to MAX_PARTICIPANTS times in a large campaign.
     *
     * @param giveawayId  Giveaway to enter.
     * @param rootIndex   Which root in the giveaway's history to prove against.
     * @param merkleProof Proof of keccak256(abi.encodePacked(msg.sender)) against that root.
     */
    function enter(uint256 giveawayId, uint256 rootIndex, bytes32[] calldata merkleProof) external whenNotPaused {
        Giveaway storage g = _giveaways[giveawayId];
        if (g.status != Status.OPEN) revert GiveawayNotOpen();
        // C5 — the effective end, so a pause inside the entry window gives the time back.
        if (block.timestamp >= effectiveEndTime(giveawayId)) revert EntriesClosed();
        if (hasEntered[giveawayId][msg.sender]) revert AlreadyEntered();

        address[] storage parts = _participants[giveawayId];
        uint256 index = parts.length;
        // Section 7.2 — the ceiling is what the creator bought, not a constant anyone can fill.
        if (index >= uint256(g.slotCap)) revert SlotsExhausted();

        bytes32[] storage roots = _eligibilityRoots[giveawayId];
        if (rootIndex >= roots.length) revert NotEligible();
        // Address leaves are 20 bytes, internal nodes are 64: no second-preimage ambiguity.
        bytes32 leaf = keccak256(abi.encodePacked(msg.sender));
        if (!MerkleProof.verify(merkleProof, roots[rootIndex], leaf)) revert NotEligible();

        hasEntered[giveawayId][msg.sender] = true;
        parts.push(msg.sender);

        // J5 — the index is the direct input to the derivation; a log without it shifts every
        // position for anyone reconstructing the draw from events.
        emit Entered(giveawayId, msg.sender, index);
    }

    // ============================================================
    // SETTLEMENT — permissionless throughout
    // ============================================================

    /**
     * @notice Close entries. Callable by anyone once the effective end time has passed.
     * @dev S1 — closing no longer asks the coordinator for anything. V1 requested randomness in
     *      this same call, so a coordinator that reverted (unregistered consumer, missing
     *      subscription, no LINK) reverted the whole close; and since the only other way out of
     *      OPEN was a creator cancellation that C1 now blocks, every campaign would have frozen
     *      at once. Here the close is pure state and the request is a separate, retryable step.
     *
     *      C2 — below MIN_PARTICIPANTS the giveaway cancels here instead, which also absorbs the
     *      zero-entrant case V1 handled separately. One rule, no exception between one and nine
     *      entrants: since a creator may enter their own campaign, an exception there would let
     *      them recover the fee at will with a single wallet.
     *
     * @param giveawayId Giveaway to close.
     */
    function closeGiveaway(uint256 giveawayId) external whenNotPaused nonReentrant {
        Giveaway storage g = _giveaways[giveawayId];
        if (g.status != Status.OPEN) revert GiveawayNotOpen();
        if (block.timestamp < effectiveEndTime(giveawayId)) revert NotDue();

        uint256 n = _participants[giveawayId].length;

        if (n < MIN_PARTICIPANTS) {
            // J4 — no close event for a giveaway that cancels in the same transaction.
            _cancel(giveawayId, g, REASON_BELOW_MINIMUM, n);
            return;
        }

        // Clamp: asking for more winners than entrants just means everyone wins an equal share.
        // The cast is safe, this branch only runs when n < winnersCount <= MAX_WINNERS.
        if (uint256(g.winnersCount) > n) g.winnersCount = uint32(n);

        g.status = Status.CLOSED;
        g.closedAt = uint64(block.timestamp);

        // J3 — the post-clamp count, so a reader is never shown the pre-clamp one.
        emit GiveawayClosed(giveawayId, n, g.winnersCount);
    }

    /**
     * @notice Ask Chainlink for the seed of a closed giveaway. Permissionless and retryable.
     * @dev S1 — the retry is the point. If the coordinator reverts, only this transaction fails
     *      and the giveaway stays CLOSED for anyone to try again; if it can never succeed, the
     *      CLOSED branch of {cancelStuckDraw} eventually refunds the creator in full.
     *
     *      Deliberately not pausable, unlike closing. The randomness pipeline is the one thing a
     *      pause must never interrupt: leaving this open, and {finalizeWinners} with it, means a
     *      pause can never leave a campaign with no way forward — not while its CLOSED timeout
     *      runs down, and not once its seed has landed.
     *
     * @param giveawayId Giveaway in CLOSED.
     */
    function requestDraw(uint256 giveawayId) external nonReentrant {
        Giveaway storage g = _giveaways[giveawayId];
        if (g.status != Status.CLOSED) revert NotClosed();

        uint256 requestId = vrfCoordinator.requestRandomWords(
            VRFV2PlusClient.RandomWordsRequest({
                keyHash: keyHash,
                subId: subscriptionId,
                requestConfirmations: REQUEST_CONFIRMATIONS,
                callbackGasLimit: callbackGasLimit,
                numWords: NUM_WORDS,
                extraArgs: VRFV2PlusClient._argsToBytes(VRFV2PlusClient.ExtraArgsV1({nativePayment: false}))
            })
        );
        // C9 — V1 wrote this key without looking. A colliding id would have silently repointed an
        // older giveaway's fulfilment; failing loudly here is recoverable, corruption is not.
        if (giveawayIdByRequestId[requestId] != 0) revert RequestIdCollision();

        g.status = Status.DRAW_REQUESTED;
        g.drawRequestedAt = uint64(block.timestamp);
        g.vrfRequestId = requestId;
        giveawayIdByRequestId[requestId] = giveawayId;

        emit RandomnessRequested(giveawayId, requestId);
    }

    /**
     * @notice Return a giveaway whose VRF request outlived its rescue window to CLOSED.
     * @dev S2 — this is what makes the timeout rescue a window rather than a permanent state.
     *      Once the window shuts, {cancelStuckDraw} can no longer be used against this request,
     *      so a late fulfilment is no longer racing a cancellation; and because the giveaway
     *      lands back in CLOSED, the draw can simply be requested again, or the CLOSED timeout
     *      can refund the creator. No path leaves value unreachable.
     *
     *      A stale fulfilment for the abandoned request that arrives after a new one has been
     *      made is still accepted, and that is deliberate: it is a genuine VRF seed either way,
     *      unknowable to everyone at the time it was requested, so accepting it costs nothing and
     *      rejecting it would only cost liveness.
     *
     * @param giveawayId Giveaway in DRAW_REQUESTED past DRAW_TIMEOUT + RESCUE_WINDOW.
     */
    function expireDrawRequest(uint256 giveawayId) external {
        Giveaway storage g = _giveaways[giveawayId];
        if (g.status != Status.DRAW_REQUESTED) revert NotDrawRequested();
        if (block.timestamp <= uint256(g.drawRequestedAt) + DRAW_TIMEOUT + RESCUE_WINDOW) {
            revert TimeoutNotReached();
        }

        g.status = Status.CLOSED;
        g.closedAt = uint64(block.timestamp);

        emit DrawRequestExpired(giveawayId, g.vrfRequestId);
    }

    /**
     * @notice Coordinator-only VRF fulfilment entrypoint. Never pausable (C4).
     * @dev Also the double-fulfilment guard: a second delivery finds SEED_RECEIVED rather than
     *      DRAW_REQUESTED and reverts.
     * @param requestId   The request this fulfilment answers.
     * @param randomWords One word, from which the whole winner set expands.
     */
    function rawFulfillRandomWords(uint256 requestId, uint256[] calldata randomWords) external nonReentrant {
        if (msg.sender != address(vrfCoordinator)) revert OnlyCoordinator();

        uint256 giveawayId = giveawayIdByRequestId[requestId];
        // Ids start at 1, so a zero here is a requestId this contract never made.
        if (giveawayId == 0) revert UnknownRequest();

        Giveaway storage g = _giveaways[giveawayId];
        if (g.status != Status.DRAW_REQUESTED) revert NotDrawRequested();

        uint256 seed = randomWords[0];
        g.seed = seed;
        g.status = Status.SEED_RECEIVED;

        emit SeedReceived(giveawayId, seed);
    }

    /**
     * @notice Derive and store winners from the seed already on chain. Permissionless, and
     *         batched: call it repeatedly until the giveaway is SETTLED.
     * @dev The derivation is V1's, unchanged, because the audit found nothing to change: winner i
     *      is participants[keccak256(seed, attempt) % n], an already-selected index is skipped and
     *      the attempt counter advances permanently. Termination is guaranteed by the clamp at
     *      close, so a free index always exists. The cursor persists in nextAttempt, so a batch
     *      resumes exactly where the last one stopped and the winner set depends neither on how
     *      the work was split nor on who did it.
     *
     *      The winner-position mapping doubles as the already-selected guard: one wallet, one
     *      entry makes index and wallet a bijection, so no separate selected-index mapping is
     *      needed. That halves the cold writes per winner, which is what dominates gas at
     *      MAX_WINNERS.
     *
     *      S5/J2 — each batch publishes the winners it derived, and the settlement event no
     *      longer carries the winner array. In V1 the final batch alone paid to read a thousand
     *      addresses back out of storage for one event, so the rational move was to stop one
     *      short and let somebody else finish; a large campaign could sit there indefinitely.
     *
     *      Never pausable (C4). It was, and that made SEED_RECEIVED the one state with no way
     *      out: this function is its only exit, the state carries no timestamp and therefore no
     *      timeout, and no cancellation route accepts it. A pause parked such a campaign there
     *      indefinitely, with the winners unable to claim a giveaway that had not settled and the
     *      creator unable to take the prize back, since claimCreatorRefund needs CANCELLED and
     *      both reclaim paths need SETTLED. That is the pause holding third-party funds, which is
     *      the one thing C4 says it must never do. Opening it costs nothing: no transfer, no
     *      external call, and nothing here is caller-steerable — the seed is already on chain and
     *      the derivation is deterministic, so the caller picks neither the winners nor their
     *      order.
     *
     * @param giveawayId Giveaway in SEED_RECEIVED.
     */
    function finalizeWinners(uint256 giveawayId) external nonReentrant {
        Giveaway storage g = _giveaways[giveawayId];
        if (g.status != Status.SEED_RECEIVED) revert NotSeedReceived();

        address[] storage parts = _participants[giveawayId];
        address[] storage wins = _winners[giveawayId];

        uint256 n = parts.length;
        uint256 target = g.winnersCount;
        uint256 seed = g.seed;

        uint256 attempt = g.nextAttempt;
        uint256 written = wins.length;
        uint256 from = written;
        uint256 steps;

        while (written < target && steps < FINALIZE_STEPS) {
            address candidate = parts[uint256(keccak256(abi.encode(seed, attempt))) % n];
            unchecked {
                ++attempt;
                ++steps;
            }
            if (_winnerSlot[giveawayId][candidate] != 0) continue; // index already taken, skip it
            unchecked {
                ++written;
            }
            _winnerSlot[giveawayId][candidate] = written; // position plus one
            wins.push(candidate);
        }

        // J2 — the progress signal V1 had no equivalent for. A thousand-winner draw took at least
        // ten calls that wrote state and emitted nothing, which was the one gap that could not be
        // reconstructed from logs.
        if (written > from) emit WinnersDerived(giveawayId, from, _winnersSlice(wins, from, written));

        if (written < target) {
            // SafeCast rather than a raw cast: a silent truncation would rewind the cursor and
            // re-derive an attempt already spent.
            g.nextAttempt = SafeCast.toUint32(attempt);
            return;
        }

        g.status = Status.SETTLED;
        g.settledAt = uint64(block.timestamp);

        // Revenue is recognised only here, at the one state that means the giveaway actually ran.
        // Every cancellation path decides the fee separately, under C3.
        feesAccrued[g.feeToken] += g.feeAmount;
        // Section 7.2 — the creator bought a ceiling and the campaign ran to it or under it;
        // slots are not returned on the successful path. Only the below-minimum cancellation
        // gives any of them back, and only in proportion (C3).
        feesAccrued[usdc] += g.slotsPaid;

        uint256 share;
        uint256 remainder;
        if (g.prizeKind == PrizeKind.TOKEN) {
            share = g.prizeAmount / target;
            remainder = g.prizeAmount - share * target;
        } else {
            share = 1; // section 8.3: one item per winner
        }

        // J1 — V1 published a truncated share that the first winner never actually received.
        emit GiveawaySettled(giveawayId, g.winnersCount, share, remainder);
    }

    /// @dev Copies one batch out of the winners array. Bounded by FINALIZE_STEPS on the
    ///      finalisation path and by the caller's page size on the view path.
    function _winnersSlice(address[] storage wins, uint256 from, uint256 to)
        private
        view
        returns (address[] memory out)
    {
        out = new address[](to - from);
        for (uint256 i; i < out.length; ++i) {
            out[i] = wins[from + i];
        }
    }

    // ============================================================
    // CANCELLATION
    // ============================================================

    /**
     * @notice Rescue a giveaway whose draw never arrived. Permissionless.
     * @dev Two entries, both refunding the creator in full because both are the platform's
     *      infrastructure failing rather than the creator's campaign (C3).
     *
     *      From CLOSED (S1): the request could not be made at all within DRAW_TIMEOUT.
     *
     *      From DRAW_REQUESTED: the request was made and the coordinator went quiet. Eligible
     *      only inside RESCUE_WINDOW after the timeout (S2), where V1 left it eligible forever.
     *      Forever is what made the race worth running: a late fulfilment carries, in its own
     *      calldata, everything needed to derive the winner set off-chain, so anyone who did not
     *      like the answer could cancel the draw ahead of it and void a valid one. Bounding the
     *      window bounds the exposure, and {expireDrawRequest} then returns the giveaway to
     *      CLOSED so nothing is stranded by the bound.
     *
     * @param giveawayId Giveaway stuck in CLOSED or DRAW_REQUESTED.
     */
    function cancelStuckDraw(uint256 giveawayId) external whenNotPaused nonReentrant {
        Giveaway storage g = _giveaways[giveawayId];
        Status status = g.status;

        if (status == Status.DRAW_REQUESTED) {
            uint256 opensAt = uint256(g.drawRequestedAt) + DRAW_TIMEOUT;
            if (block.timestamp <= opensAt) revert TimeoutNotReached();
            if (block.timestamp > opensAt + RESCUE_WINDOW) revert RescueWindowClosed();
        } else if (status == Status.CLOSED) {
            if (block.timestamp <= uint256(g.closedAt) + DRAW_TIMEOUT) revert TimeoutNotReached();
        } else {
            revert NotDrawRequested();
        }

        _cancel(giveawayId, g, REASON_VRF_TIMEOUT, _participants[giveawayId].length);
    }

    /**
     * @notice Creator abandons a giveaway nobody has entered yet.
     * @dev C1 — blocked the moment the first entry lands. In V1 this was callable at any point
     *      while OPEN, and because OPEN survived the end time until somebody called close, the
     *      window included the period where the entrant list was already final and publicly
     *      readable. From the first entry a campaign now runs to its end, whatever the creator
     *      thinks of the field. Cancelling with a penalty fee was considered and rejected: it
     *      does nothing for people who spent time meeting the eligibility criteria.
     *
     *      C3 — the fee is retained even with nobody entered, which is what stops the contract
     *      being a free test harness. The slots come back in full: none were consumed.
     *
     * @param giveawayId Giveaway to cancel.
     */
    function cancelByCreator(uint256 giveawayId) external whenNotPaused nonReentrant {
        Giveaway storage g = _giveaways[giveawayId];
        if (g.status != Status.OPEN) revert GiveawayNotOpen();
        if (msg.sender != g.creator) revert NotCreator();
        if (_participants[giveawayId].length != 0) revert HasParticipants();

        _cancel(giveawayId, g, REASON_CREATOR, 0);
    }

    /**
     * @dev The ONLY path to Status.CANCELLED. All three routes funnel through here, so the split
     *      between what the protocol keeps and what the creator gets back is decided in exactly
     *      one place, and the retained part is recognised as revenue at the moment of
     *      cancellation, as C3 requires. Two independent writers of a terminal state is how funds
     *      get stranded; do not set Status.CANCELLED anywhere else.
     */
    function _cancel(uint256 giveawayId, Giveaway storage g, uint8 reason, uint256 n) private {
        g.status = Status.CANCELLED;
        g.cancelReason = reason;

        (uint256 feeRetained, uint256 slotsRetained) = _cancelSplit(g, n);

        if (feeRetained != 0) feesAccrued[g.feeToken] += feeRetained;
        if (slotsRetained != 0) feesAccrued[usdc] += slotsRetained;

        emit GiveawayCancelled(giveawayId, reason, feeRetained, slotsRetained);
    }

    /**
     * @notice What a cancelled giveaway keeps from the creator, by route (C3).
     * @dev The single source of truth for the cancellation economics, read both when the
     *      cancellation is recorded and when the creator collects, so the two can never disagree.
     *
     *      Creator cancellation and below-minimum both retain the prize fee, for the same reason:
     *      to stop the contract funding test campaigns. Below-minimum additionally keeps the
     *      slots in proportion to the entrants it did attract, since the verification behind each
     *      of those entries really was paid for. A VRF timeout retains nothing, because there it
     *      is the platform that failed, not the campaign.
     *
     * @param g Giveaway, with cancelReason already written.
     * @param n Entrants at the moment of cancellation, which is final once cancelled.
     */
    function _cancelSplit(Giveaway storage g, uint256 n)
        private
        view
        returns (uint256 feeRetained, uint256 slotsRetained)
    {
        if (g.cancelReason == REASON_VRF_TIMEOUT) return (0, 0);

        feeRetained = g.feeAmount;
        if (g.cancelReason == REASON_BELOW_MINIMUM) {
            slotsRetained = (g.slotsPaid * n) / uint256(g.slotCap);
        }
    }

    // ============================================================
    // CLAIMS — pull-payment, never pausable (C4)
    // ============================================================

    /**
     * @notice Winner collects their share of a settled giveaway.
     * @dev Pull-payment: a token or collection that reverts for one recipient blocks only that
     *      recipient's own call. No other winner, no other giveaway and no creator refund is
     *      affected.
     *
     *      C6 — the 90-day deadline applies to token and NFT alike, one rule not two. Past it the
     *      claim closes and the creator can recover what nobody took, so a prize is never left in
     *      a module forever.
     *
     *      Never pausable: a winner already derived has an acquired right, and the pause exists
     *      to stop a problem spreading, never to hold somebody else's money.
     *
     * @param giveawayId Settled giveaway.
     */
    function claimPrize(uint256 giveawayId) external nonReentrant {
        Giveaway storage g = _giveaways[giveawayId];

        uint256 amount = claimable(giveawayId, msg.sender);
        if (amount == 0) revert NothingToClaim();
        if (block.timestamp > uint256(g.settledAt) + CLAIM_DEADLINE) revert ClaimExpired();

        // Section 8.3 — the position is the index of the item this winner is owed.
        uint256 index = _winnerSlot[giveawayId][msg.sender] - 1;

        prizeClaimed[giveawayId][msg.sender] = true;
        g.prizeDelivered += amount;

        IPrizeModule(g.prizeModule).deliver(giveawayId, msg.sender, index, amount);

        emit PrizeClaimed(giveawayId, msg.sender, amount);
    }

    /**
     * @notice Creator collects what a cancelled giveaway owes them: the prize back from the
     *         module, plus whatever fee and slot credit C3 leaves them.
     * @param giveawayId Cancelled giveaway.
     */
    function claimCreatorRefund(uint256 giveawayId) external nonReentrant {
        Giveaway storage g = _giveaways[giveawayId];
        if (g.status != Status.CANCELLED) revert NotCancelled();
        if (msg.sender != g.creator) revert NotCreator();
        if (creatorRefunded[giveawayId]) revert AlreadyRefunded();

        (uint256 feeRetained, uint256 slotsRetained) = _cancelSplit(g, _participants[giveawayId].length);
        uint256 feeRefund = g.feeAmount - feeRetained;
        uint256 slotsRefund = g.slotsPaid - slotsRetained;
        uint256 prize = g.prizeAmount;
        IERC20 feeToken = g.feeToken;

        creatorRefunded[giveawayId] = true;
        committed[feeToken] -= feeRefund;
        committed[usdc] -= slotsRefund;
        g.prizeDelivered = prize;

        if (feeRefund != 0) feeToken.safeTransfer(msg.sender, feeRefund);
        if (slotsRefund != 0) usdc.safeTransfer(msg.sender, slotsRefund);
        IPrizeModule(g.prizeModule).returnToCreator(giveawayId, msg.sender, prize);

        emit CreatorRefunded(giveawayId, feeRefund, slotsRefund, prize);
    }

    /**
     * @notice Creator recovers the NFT items left over when the winner count was clamped at
     *         close. Available immediately once the giveaway settles, with no waiting period.
     * @dev C6 — the ninety-day deadline exists to protect winners who can still come and claim.
     *      It does not apply here, because the items beyond the clamped winner count never had
     *      an owner to protect: the reduction happens at close, and the arithmetic is settled and
     *      public from that instant. Making the creator wait ninety days for items nobody won
     *      would be a penalty with no beneficiary. That is why section 8.4 releases them
     *      immediately, and why this is a function of its own rather than a branch inside
     *      {reclaimUnclaimedPrize}: two different questions, two different conditions.
     *
     *      Only an NFT campaign can have a surplus. A token prize is always divided across the
     *      clamped winner set in full, so there is never anything left over.
     *
     *      The two reclaim paths draw on disjoint pools and cannot double-spend: the surplus is
     *      the item positions at or above the winner count, and a winner's claim is always a
     *      position below it. The flag stops this path running twice, and
     *      {reclaimUnclaimedPrize} sets it too, because that one sweeps everything the module
     *      still holds and so covers the surplus as well.
     *
     * @param giveawayId Settled NFT giveaway whose winner count was clamped at close.
     */
    function reclaimClampSurplus(uint256 giveawayId) external nonReentrant {
        Giveaway storage g = _giveaways[giveawayId];
        if (g.status != Status.SETTLED) revert NotSettled();
        if (msg.sender != g.creator) revert NotCreator();
        if (clampSurplusReclaimed[giveawayId]) revert ClampSurplusAlreadyReclaimed();
        // Ordered before the subtraction on purpose: a token campaign may legitimately hold a
        // prize amount smaller than its winner count, and the difference would underflow into a
        // panic instead of naming what the caller actually got wrong.
        if (g.prizeKind != PrizeKind.NFT) revert NotNftGiveaway();

        // Section 8.4 — winnersCount equalled the item count at creation and can only have been
        // clamped downwards at close, so this difference is exactly the items nobody won.
        uint256 surplus = g.prizeAmount - uint256(g.winnersCount);
        if (surplus == 0) revert NoClampSurplus();

        clampSurplusReclaimed[giveawayId] = true;
        g.prizeDelivered += surplus;

        IPrizeModule(g.prizeModule).returnToCreator(giveawayId, msg.sender, surplus);

        emit ClampSurplusReclaimed(giveawayId, surplus);
    }

    /**
     * @notice Creator recovers prize that winners never came to claim, once the deadline passes.
     * @dev C6 — ninety days from settlement, for token and NFT alike, one rule not two. In V1
     *      there was no deadline and no recovery at all, so a share nobody claimed stayed in the
     *      contract permanently.
     *
     *      Sweeps everything the module still holds for this giveaway, so a creator who never
     *      called {reclaimClampSurplus} gets the clamp surplus back here too, in the same call.
     *
     * @param giveawayId Settled giveaway past its claim deadline.
     */
    function reclaimUnclaimedPrize(uint256 giveawayId) external nonReentrant {
        Giveaway storage g = _giveaways[giveawayId];
        if (g.status != Status.SETTLED) revert NotSettled();
        if (msg.sender != g.creator) revert NotCreator();
        if (block.timestamp <= uint256(g.settledAt) + CLAIM_DEADLINE) revert DeadlineNotReached();

        uint256 remaining = g.prizeAmount - g.prizeDelivered;
        if (remaining == 0) revert NothingToClaim();

        g.prizeDelivered = g.prizeAmount;
        // Covers the surplus too, so the dedicated path must not run afterwards and ask the
        // module for items it no longer holds.
        clampSurplusReclaimed[giveawayId] = true;

        IPrizeModule(g.prizeModule).returnToCreator(giveawayId, msg.sender, remaining);

        emit UnclaimedPrizeReclaimed(giveawayId, remaining);
    }

    // ============================================================
    // OWNER — pause, unpause, withdrawFees, sweep, module registry, bridge, prices.
    // Nothing here can pick a winner, touch a prize, or block a claim.
    // ============================================================

    /**
     * @notice Halt creation, entry, closing and cancellation. Not finalisation (C4).
     * @dev C4 — V1 carried this modifier on two of forty-seven functions, which made it a switch
     *      for entries rather than a brake for emergencies. The pause is broad now, and claims
     *      and refunds stay open throughout: it exists to stop a problem spreading, never to hold
     *      third-party funds.
     *
     *      C5 — the clock starts here, and every giveaway created before this moment has its
     *      entry window extended by however long the pause lasts. Otherwise pausing through an
     *      entry window would be a way to drive a campaign below MIN_PARTICIPANTS on purpose and
     *      have it cancel.
     */
    function pause() external onlyOwner {
        pausedAt = uint64(block.timestamp);
        _pause();
    }

    /// @notice Resume. Banks the pause just ended into the extension every live campaign gets.
    function unpause() external onlyOwner {
        totalPausedTime += uint64(block.timestamp - uint256(pausedAt));
        pausedAt = 0;
        _unpause();
    }

    /**
     * @notice Withdraw accumulated protocol fees for one token.
     * @dev Only fees from settled giveaways, and those retained under C3, are ever in this
     *      balance, so a withdrawal can never take money a creator is still owed.
     * @param token Fee token to collect.
     */
    function withdrawFees(IERC20 token) external onlyOwner nonReentrant {
        uint256 amount = feesAccrued[token];
        if (amount == 0) revert NothingToClaim();

        feesAccrued[token] = 0;
        committed[token] -= amount;

        token.safeTransfer(msg.sender, amount);

        emit FeesWithdrawn(token, amount);
    }

    /**
     * @notice Remove tokens sent here that no campaign and no fee balance accounts for.
     * @dev C7 — V1 had no way to reach them at all. The surplus is computed by the contract, not
     *      declared by the caller: real balance minus everything owed to anyone. The owed side is
     *      maintained as O(1) counters on the state transitions rather than by walking campaigns,
     *      and it reverts rather than paying out zero, so a mistake is loud.
     *
     *      Prizes are structurally outside this: they are custodied by the modules and never pass
     *      through this contract, so no sweep here can reach one. The equivalent sweep for a
     *      module's own stray deposits belongs to that module.
     *
     * @param token Token to sweep.
     */
    function sweepSurplus(IERC20 token) external onlyOwner nonReentrant {
        uint256 balance = token.balanceOf(address(this));
        uint256 owed = committed[token];
        if (balance <= owed) revert NoSurplus();

        uint256 surplus = balance - owed;
        token.safeTransfer(msg.sender, surplus);

        emit SurplusSwept(token, surplus);
    }

    /**
     * @notice Allow or disallow a prize module for new giveaways.
     * @dev Section 2.3 — read only at creation. A campaign already bound to a module keeps it
     *      whatever happens here, so registering a new prize type cannot reach anything running
     *      and de-registering cannot strand a prize.
     * @param module  Module address. Must be a contract when being allowed.
     * @param allowed Whether new giveaways may choose it.
     */
    function registerModule(address module, bool allowed) external onlyOwner {
        if (module == address(0)) revert InvalidAddress();
        if (allowed && module.code.length == 0) revert InvalidAddress();

        isModuleRegistered[module] = allowed;

        emit ModuleRegistered(module, allowed);
    }

    /// @notice Move the address allowed to publish eligibility roots.
    /// @param newBridge The new bridge address.
    function setBridge(address newBridge) external onlyOwner {
        if (newBridge == address(0)) revert InvalidAddress();

        emit BridgeChanged(bridge, newBridge);
        bridge = newBridge;
    }

    /// @notice Set the price of one entry slot. Never touches a campaign already created: each
    ///         one paid at the rate current when it bought, and a reload pays at the rate current
    ///         when it reloads (section 7.3).
    /// @param newPrice New price in USDC units.
    function setPricePerSlot(uint256 newPrice) external onlyOwner {
        if (newPrice == 0) revert InvalidPrice();

        emit PricePerSlotChanged(pricePerSlot, newPrice);
        pricePerSlot = newPrice;
    }

    /// @notice Set the floor on an NFT campaign fee. Charged at creation, so an adjustment never
    ///         reaches a campaign already running.
    /// @param newFee New floor in USDC units.
    function setNftMinFee(uint256 newFee) external onlyOwner {
        if (newFee == 0) revert InvalidPrice();

        emit NftMinFeeChanged(nftMinFee, newFee);
        nftMinFee = newFee;
    }

    /**
     * @notice Disabled. Ownership can be transferred, never abandoned.
     * @dev C8 — the inherited version is one step and irreversible, and Ownable2Step does not
     *      cover it. One accidental call would put every accrued fee permanently out of reach and
     *      leave nobody able to register a module or pause the contract.
     */
    function renounceOwnership() public pure override {
        revert RenounceDisabled();
    }

    // ============================================================
    // VIEWS
    // ============================================================

    /**
     * @notice When entries really close for a giveaway, pause time included (C5).
     * @dev The single source of truth for every time check in this contract, deliberately: entry
     *      and close reading different clocks would be a severe bug, and V1's pause could
     *      otherwise be used to steer a campaign into cancellation. Exposed so the UI counts down
     *      to the same instant the contract enforces.
     * @param giveawayId Giveaway to time.
     */
    function effectiveEndTime(uint256 giveawayId) public view returns (uint256) {
        Giveaway storage g = _giveaways[giveawayId];
        return uint256(g.endTime) + (accruedPausedTime() - uint256(g.pausedOffset));
    }

    /// @notice Total pause time to date, including a pause currently in force.
    function accruedPausedTime() public view returns (uint256) {
        uint256 total = totalPausedTime;
        if (paused()) total += block.timestamp - uint256(pausedAt);
        return total;
    }

    /// @notice The full giveaway record. Participants, winners and roots are read separately.
    function getGiveaway(uint256 giveawayId) external view returns (Giveaway memory) {
        return _giveaways[giveawayId];
    }

    function getParticipantsCount(uint256 giveawayId) external view returns (uint256) {
        return _participants[giveawayId].length;
    }

    /// @dev O(n) memory, up to MAX_PARTICIPANTS. An off-chain caller should rebuild large lists
    ///      from the Entered logs instead.
    function getParticipants(uint256 giveawayId) external view returns (address[] memory) {
        return _participants[giveawayId];
    }

    function getWinnersCount(uint256 giveawayId) external view returns (uint256) {
        return _winners[giveawayId].length;
    }

    /**
     * @notice Winners in selection order, one page at a time. Partially filled while a batched
     *         finalisation is still in flight.
     * @dev Paginated per S5, which is the other half of taking the winner array out of the
     *      settlement event: the data stays readable, it just stops being paid for by whoever
     *      happens to send the last batch.
     * @param giveawayId Giveaway to read.
     * @param from       Zero-based winner position to start at.
     * @param count      Maximum winners to return. Truncated at the end of the list.
     */
    function getWinners(uint256 giveawayId, uint256 from, uint256 count)
        external
        view
        returns (address[] memory)
    {
        address[] storage wins = _winners[giveawayId];
        uint256 length = wins.length;
        if (from >= length) return new address[](0);

        uint256 to = from + count;
        if (to > length) to = length;

        return _winnersSlice(wins, from, to);
    }

    /// @notice Whether a wallet was drawn in a giveaway.
    function isWinner(uint256 giveawayId, address wallet) external view returns (bool) {
        return _winnerSlot[giveawayId][wallet] != 0;
    }

    /// @notice A winner's zero-based position in the derived order, which is also the index of
    ///         the item they are owed in an NFT campaign (section 8.3). Reverts if not a winner.
    function winnerIndex(uint256 giveawayId, address wallet) external view returns (uint256) {
        uint256 slot = _winnerSlot[giveawayId][wallet];
        if (slot == 0) revert NothingToClaim();
        return slot - 1;
    }

    /// @notice The whole append-only eligibility root history for a giveaway (section 4.2).
    function getEligibilityRoots(uint256 giveawayId) external view returns (bytes32[] memory) {
        return _eligibilityRoots[giveawayId];
    }

    function getEligibilityRootsCount(uint256 giveawayId) external view returns (uint256) {
        return _eligibilityRoots[giveawayId].length;
    }

    /// @notice Entry slots still available on a giveaway (section 7.2).
    function slotsRemaining(uint256 giveawayId) external view returns (uint256) {
        uint256 used = _participants[giveawayId].length;
        uint256 cap = uint256(_giveaways[giveawayId].slotCap);
        return cap > used ? cap - used : 0;
    }

    /**
     * @notice What a wallet can withdraw from a giveaway right now.
     * @dev The indivisible remainder goes to the first derived winner, deterministically, so the
     *      sum over all winners is exactly the prize with nothing stranded. Carried from V1
     *      unchanged.
     * @param giveawayId Giveaway to price.
     * @param wallet     Wallet to price it for.
     */
    function claimable(uint256 giveawayId, address wallet) public view returns (uint256) {
        Giveaway storage g = _giveaways[giveawayId];
        if (g.status != Status.SETTLED) return 0;

        uint256 slot = _winnerSlot[giveawayId][wallet];
        if (slot == 0) return 0;
        if (prizeClaimed[giveawayId][wallet]) return 0;

        if (g.prizeKind == PrizeKind.NFT) return 1; // section 8.3: one item per winner

        uint256 target = g.winnersCount;
        uint256 share = g.prizeAmount / target;
        if (slot == 1) share += g.prizeAmount - share * target;
        return share;
    }

    /**
     * @notice The protocol fee {createGiveaway} would charge right now.
     * @param kind   Prize kind of the campaign.
     * @param amount Prize amount for a token campaign, declared value for an NFT one.
     */
    function currentFee(PrizeKind kind, uint256 amount) public view returns (uint256) {
        if (kind == PrizeKind.NFT) {
            uint256 fee = (amount * NFT_FEE_BPS) / BPS;
            return fee < nftMinFee ? nftMinFee : fee;
        }
        return (amount * FEE_BPS) / BPS;
    }

    /// @notice What buying `slots` entry slots costs right now, in USDC units (section 7.2).
    function currentSlotCost(uint256 slots) external view returns (uint256) {
        return slots * pricePerSlot;
    }

    /**
     * @notice Giveaways past their effective end and still OPEN: the {closeGiveaway} work queue.
     * @dev C10 — cursored, where V1 swept the whole id space on every call. Both the scan and the
     *      result are bounded by `limit`, and `nextId` is where to resume, so a caller pages
     *      through the id space in fixed-cost calls instead of one call that grows forever.
     * @param startId First id to examine. Ids start at 1.
     * @param limit   Maximum ids to examine in this call.
     * @return ids    Closeable giveaways found in the examined range.
     * @return nextId Id to pass as `startId` next time. Past lastGiveawayId means done.
     */
    function getCloseableGiveaways(uint256 startId, uint256 limit)
        external
        view
        returns (uint256[] memory ids, uint256 nextId)
    {
        uint256 last = lastGiveawayId;
        if (startId == 0) startId = 1;

        uint256 end = startId + limit;
        if (end > last + 1) end = last + 1;

        uint256[] memory buf = new uint256[](end > startId ? end - startId : 0);
        uint256 count;

        for (uint256 id = startId; id < end; ++id) {
            if (_giveaways[id].status == Status.OPEN && block.timestamp >= effectiveEndTime(id)) {
                buf[count] = id;
                ++count;
            }
        }

        ids = new uint256[](count);
        for (uint256 i; i < count; ++i) {
            ids[i] = buf[i];
        }
        nextId = end > startId ? end : startId;
    }

    /**
     * @notice Giveaways holding a seed and still awaiting winners: the {finalizeWinners} work
     *         queue. An id stays listed until its last batch lands.
     * @dev Cursored for the same reason as {getCloseableGiveaways} (C10).
     * @param startId First id to examine. Ids start at 1.
     * @param limit   Maximum ids to examine in this call.
     * @return ids    Finalisable giveaways found in the examined range.
     * @return nextId Id to pass as `startId` next time. Past lastGiveawayId means done.
     */
    function getFinalizableGiveaways(uint256 startId, uint256 limit)
        external
        view
        returns (uint256[] memory ids, uint256 nextId)
    {
        uint256 last = lastGiveawayId;
        if (startId == 0) startId = 1;

        uint256 end = startId + limit;
        if (end > last + 1) end = last + 1;

        uint256[] memory buf = new uint256[](end > startId ? end - startId : 0);
        uint256 count;

        for (uint256 id = startId; id < end; ++id) {
            if (_giveaways[id].status == Status.SEED_RECEIVED) {
                buf[count] = id;
                ++count;
            }
        }

        ids = new uint256[](count);
        for (uint256 i; i < count; ++i) {
            ids[i] = buf[i];
        }
        nextId = end > startId ? end : startId;
    }
}
